#!/usr/bin/env python3
"""
Round 203o (culprits-tiles-more), 14 October 2026.

- bodies.py: globe pictures stitched from Trek tiles; the Moon list's key and
  totals kept apart from its rows.

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/bodies.py': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round203o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round203o_tiles: wrote {path}")
    if not changed:
        print("round203o_tiles: already applied")


if __name__ == "__main__":
    main()
